package com.bank.chain;

import java.util.*;

public class ApprovalChainAuditor {

    public int maxApprovalDepth(ChainNode root) {
        if (root == null) return 0;
        Queue<ChainNode> queue = new LinkedList<>();
        queue.offer(root);
        int depth = 0;
        while (!queue.isEmpty()) {
            depth++;                          // one increment per non-empty level
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                ChainNode node = queue.poll();
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
        }
        return depth;                         // number of levels = max depth
    }
}
