package com.bank.chain;

import java.util.logging.Logger;

public class MaxDepthDemo {
    private static final Logger log = Logger.getLogger(MaxDepthDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3
        //          /       \
        //         4         5
        //                    \
        //                     6     (longest chain = 4 levels)
        ChainNode root = new ChainNode(1);
        root.left = new ChainNode(2);
        root.right = new ChainNode(3);
        root.left.left = new ChainNode(4);
        root.right.right = new ChainNode(5);
        root.right.right.right = new ChainNode(6);

        log.info("Maximum approval chain depth: " + new ApprovalChainAuditor().maxApprovalDepth(root));
    }
}
